index 0000000..22d8fe8
--- /dev/null
+++ b/packages/agent/src/retry.ts
@@ -0,0 +1,59 @@
+// Wraps a provider-touching call (planner, reflection) with turn-level retry so a
+// multi-minute provider outage (e.g. GLM 429 bursts) doesn't kill the task from a
+// path that bypasses sendToProvider. sendToProvider has its own inline equivalent.
+export async function withProviderRetry<T>(
+  label: string,
+  fn: () => Promise<T>,
+  signal?: AbortSignal,
+  logger: { warn: (msg: string, data?: Record<string, unknown>) => void } = console
+): Promise<T> {
+  const backoffsMs = [30_000, 60_000, 90_000];
+  for (let attempt = 0; ; attempt++) {
+    try {
+      return await fn();
+    } catch (err) {
+      if (attempt >= backoffsMs.length) throw err;
+      const waitMs = backoffsMs[attempt];
+      logger.warn(`${label} call failed, retrying after backoff`, {
+        attempt: attempt + 1,
+        waitMs,
+        error: err instanceof Error ? err.message : String(err),
+      });
+      await abortableSleep(waitMs, signal);
+    }
+  }
+}
+
+/**
+ * Sleep for `ms` milliseconds, returning early if `signal` aborts.
+ * Rejects with an `AbortError` when the signal is aborted, matching the
+ * DOMException pattern used elsewhere in the agent (e.g. sendToProvider).
+ */
+export function abortableSleep(ms: number, signal?: AbortSignal): Promise<void> {
+  return new Promise((resolve, reject) => {
+    if (signal?.aborted) {
+      reject(new DOMException('AbortError', 'AbortError'));
+      return;
+    }
+
+    let timer: NodeJS.Timeout | null = null;
+    const onAbort = (): void => {
+      if (timer) {
+        clearTimeout(timer);
+        timer = null;
+      }
+      reject(new DOMException('AbortError', 'AbortError'));
+    };
+
+    if (signal) {
+      signal.addEventListener('abort', onAbort, { once: true });
+    }
+
+    timer = setTimeout(() => {
+      if (signal) {
+        signal.removeEventListener('abort', onAbort);
+      }
+      resolve();
+    }, ms);
+  });
+}
